from google.cloud import documentai_v1 as documentai
import os

os.environ["GOOGLE_APPLICATION_CREDENTIALS"] = "/path/to/key.json"

client = documentai.DocumentProcessorServiceClient()
name = f"projects/{os.getenv('GOOGLE_CLOUD_PROJECT')}/locations/us/processors/{os.getenv('PROCESSOR_ID')}"
with open("invoice.pdf", "rb") as file:
    document = {"content": file.read(), "mime_type": "application/pdf"}
input_config = {"document": document}
request = {"name": name, "input_config": input_config}
result = client.process_document(request=request)
document = result.document
fields = {}
for entity in document.entities:
    if entity.type_ == "VENDOR":
        fields["vendor"] = entity.text
    elif entity.type_ == "DATE":
        fields["date"] = entity.text
    elif entity.type_ == "TOTAL":
        fields["total"] = entity.text
    elif entity.type_ == "LINE_ITEM":
        fields.setdefault("line_items", []).append(entity.text)
print(fields)
